191→func allHooksPresent(hooks kiroHooks, localDev bool) bool {
192→	var cmdPrefix string
193→	if localDev {
194→		cmdPrefix = localDevCmdPrefix + "hooks kiro "
195→	} else {
196→		cmdPrefix = prodHookCmdPrefix
197→	}
198→
199→	return hookCommandExists(hooks.AgentSpawn, cmdPrefix+HookNameAgentSpawn) &&
200→		hookCommandExists(hooks.UserPromptSubmit, cmdPrefix+HookNameUserPromptSubmit) &&
201→		hookCommandExists(hooks.PreToolUse, cmdPrefix+HookNamePreToolUse) &&
202→		hookCommandExists(hooks.PostToolUse, cmdPrefix+HookNamePostToolUse) &&
203→		hookCommandExists(hooks.Stop, cmdPrefix+HookNameStop)
204→}
