206→func hookCommandExists(entries []kiroHookEntry, command string) bool {
207→	for _, entry := range entries {
208→		if entry.Command == command {
209→			return true
210→		}
211→	}
212→	return false
213→}
214→
215→func isEntireHook(command string) bool {
216→	for _, prefix := range entireHookPrefixes {
217→		if strings.HasPrefix(command, prefix) {
218→			return true
219→		}
220→	}
221→	return false
222→}
223→
224→func hasEntireHook(entries []kiroHookEntry) bool {
225→	for _, entry := range entries {
226→		if isEntireHook(entry.Command) {
227→			return true
228→		}
229→	}
230→	return false
231→}
